// Normalises a fee / payment event so this workflow can be executed on its own.
// Accepts: foi-fee-payment / foi-manage-payment items from FOI Request Routing (normalised fields +
// `payload` + `metadata`), the snake_case inputs sent by the IAO sub-workflows (feeAction initiate/cancel),
// and foi-payment-expired items from FOI Payment Expiry SLA Job.
// Replaces the old Wait-based model: each outcome (PAID / CANCELLED / EXPIRED) is its own execution.
try {

const src = $input.first().json || {};

const parseJson = (value) => {
  if (value && typeof value === 'object') return value;
  if (typeof value === 'string' && value.trim()) {
    try { return JSON.parse(value); } catch (e) {
      try { return JSON.parse(value.replace(/'/g, '"')); } catch (e2) { return {}; }
    }
  }
  return {};
};
const first = (...values) => {
  for (const v of values) { if (v !== undefined && v !== null && v !== '') return v; }
  return null;
};
// const str = (v) => (v === undefined || v === null ? '' : String(v));
const str = (v) =>
  v === undefined || v === null
    ? ''
    : typeof v === 'object'
      ? JSON.stringify(v)
      : typeof v === 'string'
        ? v
        : String(v);

const bool = (v) => v === true || (typeof v === 'string' && v.trim().toLowerCase() === 'true');

const metadata = parseJson(src.metadata);
const foiRequestMetaData = parseJson(metadata?.foiRequestMetaData);
const event = str(src.event);
const eventId = str(src.eventId);
const occurredAt = str(src.occurredAt);
const status = str(first(src?.status, metadata?.status));
const category = str(src.category);
const paymentStatus = str(first(src.paymentStatus, metadata?.paymentstatus)).toUpperCase();

let feeAction = str(src.feeAction);
if (!feeAction) {
  if (event === 'foi-fee-payment' || category === 'foi-fee-payment') {
    feeAction = 'initiate';
  } else if (event === 'foi-payment-expired') {
    feeAction = 'expire';
  } else if (event === 'foi-manage-payment' || category === 'foi-manage-payment') {
    feeAction = paymentStatus === 'PAID' ? 'paid' : (paymentStatus === 'CANCELLED' ? 'cancel' : (paymentStatus === 'EXPIRED' ? 'expire' : 'unsupported'));
  } else {
    feeAction = 'unsupported';
  }
}

const fileNumber = str(src.fileNumber);
const applicantCorrespondenceId = str(first(src.applicantCorrespondenceId, foiRequestMetaData?.applicantcorrespondenceid, metadata?.applicantCorrespondenceId));
const templateName = str(first(src.templateName, foiRequestMetaData?.templatename, metadata?.templateName));
const paymentExpiryDate = str(first(src.paymentExpiryDate, src?.slaPaymentExpiryDate, foiRequestMetaData?.paymentExpiryDate));
const paymentUrl = str(first(src?.paymentUrl, foiRequestMetaData?.paymenturl, ));

return [{
  json: {
    event,
    eventId,
    occurredAt,
    feeAction,
    category,
    applicantCorrespondenceId,
    templateName,
    paymentStatus: paymentStatus,
    isOfflinePayment: bool(src.isOfflinePayment),
    isSync: bool(src.isSync),
    isPaymentActive: bool(src.isPaymentActive),
    rawRequestId: str(first(src.rawRequestId,metadata?.rawRequestId)),
    foiRequestId: str(src.foiRequestId),
    ministryRequestId: str(src.ministryRequestId),
    serviceKey: str(src?.serviceKey),
    paymentExpiryDate,
    paymentUrl,
    status,
    previousStatus: str(src.previousStatus),
    nextStateName: str(foiRequestMetaData?.nextStateName),
    fileNumber: fileNumber,
    slaId: src.paymentSlaId,
    saveDataPayload: str(src.saveDataPayload),
    triggeredBy: str(first(src.triggeredBy, src?.event)),
    metadata: str(metadata),
    executionId: $execution.id
  }
}];

} catch (error) {
  const src = $input.first().json || {};
    return {
      json: {
        event: '',
        eventId: (src && typeof src === 'object' && typeof src.eventId === 'string') ? src.eventId : null,
        receivedEvent: (src && typeof src === 'object' && typeof src.event === 'string') ? src.event : null,
        error: true,
        errorMessage: error.message,
        metadata: src.metadata ?? null,
        executionId: $execution.id,
      },
    };
}

// Picks the payment SLA row that a PAID / CANCELLED / EXPIRED outcome applies to.
// Preference: the newest ACTIVE row, then the newest PENDING row (an initiation still in progress, so a CANCELLED
// can close it), then the newest EXPIRED row (a late PAID or CANCELLED after expiry still finds its row, as the
// Camunda instance did). PAID / CANCELLED rows are never returned as the row to work on;
// when the newest row for the request is one of them the outcome is flagged as already closed instead.
// A PAID_PENDING_SIDE_EFFECTS row (Form.io already patched, confirmation email not yet sent) is picked up only by a
// PAID event, so a replay resumes at the email; for any other outcome it counts as closed (the payment is paid).
// A CANCEL_PENDING_SIDE_EFFECTS row (cancel API done, Form.io not yet patched) is picked up only by a CANCELLED event,
// so a replay skips the cancel call and resumes at the patch; for any other outcome it counts as closed (cancelled).
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id !== undefined && row.id !== null && row.id !== '');

const newest = (list) => list.slice().sort((a, b) => {
  const byCreated = String(b.createdAt ?? '').localeCompare(String(a.createdAt ?? ''));
  return byCreated !== 0 ? byCreated : Number(b.id) - Number(a.id);
})[0];

const feeAction = $('Set Event Variables').first().json.feeAction;
const open = newest(rows.filter((row) => row.sla_status === 'ACTIVE'))
  || newest(rows.filter((row) => row.sla_status === 'PENDING'))
  || (feeAction === 'paid' ? newest(rows.filter((row) => row.sla_status === 'PAID_PENDING_SIDE_EFFECTS')) : undefined)
  || (feeAction === 'cancel' ? newest(rows.filter((row) => row.sla_status === 'CANCEL_PENDING_SIDE_EFFECTS')) : undefined)
  || newest(rows.filter((row) => row.sla_status === 'EXPIRED'));
if (open) return [{ json: open, pairedItem: { item: 0 } }];

const closed = newest(rows.filter((row) => ['PAID', 'CANCELLED', 'PAID_PENDING_SIDE_EFFECTS', 'CANCEL_PENDING_SIDE_EFFECTS'].includes(row.sla_status)));
return [{
  json: closed ? { slaLookup: 'CLOSED', closedSlaId: closed.id, closedSlaStatus: closed.sla_status } : {},
  pairedItem: { item: 0 }
}];

// R09 verify-before-act. Input: the latest payment version from GET /api/foipayment/{requestid}/ministryrequest/{id}
// (FOI Backend API Manager, category foipayment-get). The API returns the record as a JSON string, so it is unwrapped first.
// Verdict:
//   EXPIRE      latest version is unpaid and not System_Cancel: safe to expire
//   PAID        latest version has a paidamount: the payment was made, the SLA row just was not closed
//   CANCELLED   latest version was written by System_Cancel
//   UNVERIFIED  lookup failed or returned no payment: do not expire; the row stays ACTIVE and the next daily run retries
const unwrap = (value) => {
  let v = value;
  for (let i = 0; i < 3 && typeof v === 'string' && v.trim(); i += 1) {
    try { v = JSON.parse(v); } catch (e) { return null; }
  }
  return v && typeof v === 'object' ? v : null;
};
const looksLikePayment = (o) => !!o && (o.paymentid !== undefined || o.version !== undefined);

const raw = $input.first()?.json ?? {};
let payment = null;
for (const candidate of [raw, raw.data, raw.body]) {
  const obj = unwrap(candidate);
  if (looksLikePayment(obj)) { payment = obj; break; }
}

if (!payment) {
  const failure = raw.error ?? raw.errorMessage ?? raw.message;
  const reason = failure
    ? 'payment lookup failed: ' + String(typeof failure === 'string' ? failure : JSON.stringify(failure)).slice(0, 200)
    : 'payment lookup returned no payment version';
  return [{ json: { verdict: 'UNVERIFIED', reason, note: reason }, pairedItem: { item: 0 } }];
}

const paid = payment.paidamount !== null && payment.paidamount !== undefined && String(payment.paidamount).trim() !== '';
const cancelled = String(payment.createdby ?? '') === 'System_Cancel';
const verdict = paid ? 'PAID' : (cancelled ? 'CANCELLED' : 'EXPIRE');
const version = payment.version ?? 'n/a';
const note = verdict === 'PAID'
  ? 'Payment expiry suppressed: the latest payment version (#' + version + ') is already PAID (paidamount ' + payment.paidamount + ') but the SLA row was still ACTIVE. Row closed as PAID; no expiry notification sent.'
  : verdict === 'CANCELLED'
    ? 'Payment expiry suppressed: the latest payment version (#' + version + ') was cancelled (System_Cancel) but the SLA row was still ACTIVE. Row closed as CANCELLED; no expiry notification sent.'
    : 'Latest payment version (#' + version + ') is unpaid and not cancelled: expiring.';

return [{
  json: {
    verdict,
    reason: note,
    note,
    paymentId: payment.paymentid ?? null,
    paymentVersion: payment.version ?? null,
    paidAmount: payment.paidamount ?? null,
    createdBy: payment.createdby ?? null,
  },
  pairedItem: { item: 0 },
}];

// G4: stop before the update call when the SLA row has no usable submission ids (the API would only say "Invalid request").
// No try/catch on purpose: the error must fail the execution so the error workflow reports it.
const sla = $('Get Active Payment SLA').first().json || {};
const events = $('Set Event Variables').first().json;
const usable = (value) => !['', 'undefined', 'null'].includes(String(value ?? '').trim());
const missing = ['form_id', 'submission_id'].filter((name) => !usable(sla[name]));
if (missing.length) {
  throw new Error(
    'Cannot update the payment form submission: ' + missing.join(' and ') + ' missing on the payment SLA row'
    + ' (row id ' + (sla.id ?? 'none') + ', status ' + (sla.sla_status ?? 'n/a') + ', ministry request ' + (events.ministryRequestId ?? 'n/a') + ').'
    + ' No update was sent.'
  );
}

// PAID: move the submission to the next state. An empty status is left out, so it is never blanked.
const status = events.nextStateName || sla.next_state_name || undefined;

return [{
  json: {
    foiRequestId: String(events.foiRequestId || sla.foi_request_id || ''),
    reqPayload: JSON.stringify({ formId: sla.form_id, submissionId: sla.submission_id, paymentStatus: 'PAID', status })
  },
  pairedItem: { item: 0 }
}];

// G4: stop before the update call when the SLA row has no usable submission ids (the API would only say "Invalid request").
// No try/catch on purpose: the error must fail the execution so the error workflow reports it.
const sla = $('Get Active Payment SLA').first().json || {};
const events = $('Set Event Variables').first().json;
const usable = (value) => !['', 'undefined', 'null'].includes(String(value ?? '').trim());
const missing = ['form_id', 'submission_id'].filter((name) => !usable(sla[name]));
if (missing.length) {
  throw new Error(
    'Cannot update the payment form submission: ' + missing.join(' and ') + ' missing on the payment SLA row'
    + ' (row id ' + (sla.id ?? 'none') + ', status ' + (sla.sla_status ?? 'n/a') + ', ministry request ' + (events.ministryRequestId ?? 'n/a') + ').'
    + ' No update was sent.'
  );
}

// CANCELLED: a cancel carries no next state, so `status` is sent only when the event supplies one, never blanked.
const status = events.status || undefined;

return [{
  json: {
    foiRequestId: String(events.foiRequestId || sla.foi_request_id || ''),
    reqPayload: JSON.stringify({ formId: sla.form_id, submissionId: sla.submission_id, paymentStatus: 'CANCELLED', status })
  },
  pairedItem: { item: 0 }
}];
